schema:
CREATE TABLE CUSTOMERS (
    ID INT,
    NAME VARCHAR(255),
    PRIMARY KEY (ID)
);

CREATE TABLE ORDERS (
    ID INT,
    CUSTOMERID VARCHAR(255),
    PRIMARY KEY (ID),
    FOREIGN KEY (CUSTOMERID) REFERENCES CUSTOMERS(ID)
);

CREATE TABLE PERSON (
    ID INT,
    EMAIL VARCHAR(255),
    PRIMARY KEY (ID)
);

